/// One applied transaction.
#[derive(Clone, Debug)]
pub struct DocumentChange {
    pub document: DocumentId,
    pub before: kate_text::Revision,
    pub after: kate_text::Revision,
    /// The text before the transaction. A rope snapshot is cheap.
    pub before_text: kate_text::Rope,
    pub transaction: kate_text::Transaction,
}

impl Workspace {
    /// Take every change since the last call, oldest first.
    pub fn drain_changes(&mut self) -> Vec<DocumentChange>;
}
